local function applyTextGlow(inst)
    if not inst or not inst:IsA("GuiObject") then return end
    if inst:IsA("TextLabel") or inst:IsA("TextBox") then
        if not inst:FindFirstChild("NeonOceanGlow") then
            local glow = Instance.new("UIStroke")
            glow.Name = "NeonOceanGlow"
            glow.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
            glow.Color = Color3.fromRGB(0, 140, 255)
            glow.Thickness = 1.1
            glow.Transparency = 0.45
            glow.Parent = inst
        end
    end
end

task.spawn(function()
    local gethui = gethui or function() return game:GetService("CoreGui") end
    local pGui = gethui() or game:GetService("CoreGui") or __LP:FindFirstChild("PlayerGui")
    
    local function setupGlow(gui)
        if not gui then return end
        local main = gui:FindFirstChild("Main")
        if main then
            local mainCont = main:FindFirstChild("MainContainer")
            if mainCont then
                local st = mainCont:FindFirstChildOfClass("UIStroke")
                if st then
                    st.Color = Color3.fromRGB(0, 240, 255)
                    st.Thickness = 1.2
                else
                    local nSt = Instance.new("UIStroke")
                    nSt.Color = Color3.fromRGB(0, 240, 255)
                    nSt.Thickness = 1.2
                    nSt.Parent = mainCont
                end
            end
        end
        for _, obj in ipairs(gui:GetDescendants()) do
            applyTextGlow(obj)
        end
        gui.DescendantAdded:Connect(function(obj)
            task.defer(function()
                applyTextGlow(obj)
            end)
        end)
    end

    for _ = 1, 40 do
        local abyssGui = (pGui and pGui:FindFirstChild("Abysslixhub GUI")) or (__LP:FindFirstChild("PlayerGui") and __LP.PlayerGui:FindFirstChild("Abysslixhub GUI"))
