    pcall(function()
        pLevel = __LP.Data.Level.Value
    end)
    if pLevel < 700 then
        Sea1 = true
    elseif pLevel < 1500 then
        Sea2 = true
    else
        Sea3 = true
    end
end
-- ==========================================
-- [TAB ESP] ESP RIÊNG THEO TỪNG SEA (tự nhận diện Sea 1 / 2 / 3)
-- Module tự chứa: không dùng chung hàm/biến ESP cũ nên không đụng tới code khác.
-- Chỉ hiện những mục thuộc đúng Sea hiện tại (boss, hoa, sự kiện biển... của Sea khác sẽ không xuất hiện).
-- ==========================================
if Tabs and Tabs["ESP"] then
    local Tab = Tabs["ESP"]

    local CollectionService = game:GetService("CollectionService")
    local PlayersSvc = game:GetService("Players")
    local WS = game:GetService("Workspace")
    local LP = PlayersSvc.LocalPlayer

    local SEA = (Sea1 and 1) or (Sea2 and 2) or (Sea3 and 3) or 0
    local SEA_NAME = (SEA > 0) and ("Sea " .. SEA) or "Không rõ"

    -- ---------- DỮ LIỆU THEO TỪNG SEA ----------
    local BOSSES = {
        [1] = { "The Gorilla King", "Bobby", "The Saw", "Yeti", "Mob Leader", "Vice Admiral", "Warden",
                "Chief Warden", "Swan", "Magma Admiral", "Fishman Lord", "Wysper", "Thunder God",
                "Cyborg", "Saber Expert", "Greybeard" },
        [2] = { "Diamond", "Jeremy", "Fajita", "Don Swan", "Smoke Admiral", "Cursed Captain",
                "Darkbeard", "Order", "Awakened Ice Admiral", "Tide Keeper" },
        [3] = { "Stone", "Island Empress", "Kilo Admiral", "Captain Elephant", "Beautiful Pirate",
                "rip_indra True Form", "rip_indra", "Longma", "Soul Reaper", "Cake Queen",
                "Cake Prince", "Dough King", "Hydra Leader", "Tyrant of the Skies" },
    }
    local ELITE = { "Diablo", "Urban", "Deandre" } -- Elite Hunter (chỉ Sea 3)

    local function toSet(list)
        local s = {}
        for _, n in ipairs(list or {}) do s[n] = true end
        return s
    end
    local BossSet = toSet(BOSSES[SEA])
    local EliteSet = toSet(ELITE)

    -- ---------- TRẠNG THÁI ----------
    local maxDist = 8000
    local active = {}   -- [key] = true/false
    local drawn = {}    -- [key] = { [instance] = { gui = BillboardGui, label = TextLabel } }
    local toggles = {}  -- [key] = toggle proxy (để nút "Tắt tất cả" lật được công tắc)
    local categories = {}

    -- Chỗ chứa BillboardGui (CoreGui/gethui, fallback PlayerGui)
    local holder = Instance.new("Folder")
    holder.Name = "AbysslixESP"
    do
        local ok = pcall(function()
            holder.Parent = (gethui and gethui()) or game:GetService("CoreGui")
        end)
        if not ok or not holder.Parent then
            holder.Parent = LP:WaitForChild("PlayerGui")
        end
    end

    local function getPart(obj)
        if not obj then return nil end
        if obj:IsA("BasePart") then return obj end
        if obj:IsA("Tool") then return obj:FindFirstChild("Handle") end
        if obj:IsA("Model") then
            return obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChildWhichIsA("BasePart", true)
        end
        return obj:FindFirstChildWhichIsA("BasePart", true)
    end

    local function myPos()
        local ch = LP.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        return hrp and hrp.Position
    end

    local function newBillboard(part, color)
        local gui = Instance.new("BillboardGui")
        gui.Name = "AbxEsp"
        gui.AlwaysOnTop = true
        gui.Size = UDim2.new(0, 200, 0, 40)
        gui.StudsOffset = Vector3.new(0, 2.5, 0)
        gui.LightInfluence = 0
        gui.Adornee = part
        local label = Instance.new("TextLabel")
        label.BackgroundTransparency = 1
        label.Size = UDim2.new(1, 0, 1, 0)
        label.Font = Enum.Font.GothamBold
        label.TextSize = 13
        label.TextWrapped = true
        label.TextColor3 = color
        label.TextStrokeTransparency = 0.4
        label.Parent = gui
        gui.Parent = holder
        return { gui = gui, label = label }
    end

    local function clearCategory(key)
        local store = drawn[key]
        if not store then return end
        for obj, e in pairs(store) do
            pcall(function() e.gui:Destroy() end)
            store[obj] = nil
        end
    end

    -- Mỗi category: collect() trả về danh sách { obj = Instance, text = "tên", color = Color3 }
    local function addCategory(key, collect)
        categories[key] = collect
        drawn[key] = {}
        active[key] = false
    end

    local function refresh()
        local origin = myPos()
        for key, collect in pairs(categories) do
            local store = drawn[key]
            if active[key] then
                local ok, list = pcall(collect)
                local seen = {}
                if ok and type(list) == "table" then
                    for _, item in ipairs(list) do
                        local part = getPart(item.obj)
                        if part and part.Parent then
                            seen[item.obj] = true
                            local e = store[item.obj]
                            if not e or not e.gui.Parent then
                                e = newBillboard(part, item.color or Color3.fromRGB(0, 240, 255))
                                store[item.obj] = e
                            end
                            e.gui.Adornee = part
                            local dist = origin and math.floor((origin - part.Position).Magnitude / 3) or 0
                            local far = origin and ((origin - part.Position).Magnitude > maxDist)
                            e.gui.Enabled = not far
                            e.label.Text = tostring(item.text) .. "\n" .. dist .. " M"
                        end
                    end
                end
                -- dọn những đối tượng đã biến mất
                for obj, e in pairs(store) do
                    if not seen[obj] then
                        pcall(function() e.gui:Destroy() end)
                        store[obj] = nil
                    end
                end
            elseif next(store) then
                clearCategory(key)
            end
        end
    end

    -- Vòng lặp cập nhật (~4 lần/giây)
    task.spawn(function()
        while task.wait(0.25) do
            pcall(refresh)
        end
    end)

    -- ---------- CÁC LOẠI ESP ----------
    local function childrenOf(parent)
        return parent and parent:GetChildren() or {}
    end

    -- Dùng chung mọi Sea
    addCategory("player", function()
        local out = {}
        for _, p in ipairs(PlayersSvc:GetPlayers()) do
            if p ~= LP and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 then
                    local lv = ""
                    pcall(function() lv = " [Lv." .. p.Data.Level.Value .. "]" end)
                    table.insert(out, { obj = p.Character, text = p.Name .. lv .. " | HP " .. math.floor(hum.Health), color = Color3.fromRGB(255, 255, 255) })
                end
            end
        end
        return out
    end)

    addCategory("fruit", function()
        local out = {}
        for _, v in ipairs(WS:GetChildren()) do
            if v:IsA("Tool") and string.find(v.Name, "Fruit") and v:FindFirstChild("Handle") then
                table.insert(out, { obj = v, text = "🍎 " .. v.Name, color = Color3.fromRGB(255, 120, 200) })
            end
        end
        return out
    end)

    addCategory("realfruit", function()
        local out = {}
        for _, folderName in ipairs({ "AppleSpawner", "PineappleSpawner", "BananaSpawner" }) do
            for _, v in ipairs(childrenOf(WS:FindFirstChild(folderName))) do
                if v:FindFirstChild("Handle") then
                    table.insert(out, { obj = v, text = v.Name, color = Color3.fromRGB(120, 255, 120) })
                end
            end
        end
        return out
    end)

    addCategory("chest", function()
        local out = {}
        for _, v in ipairs(CollectionService:GetTagged("_ChestTagged")) do
            if not v:GetAttribute("IsDisabled") then
                table.insert(out, { obj = v, text = "📦 Chest", color = Color3.fromRGB(255, 215, 0) })
            end
        end
        return out
    end)

    addCategory("island", function()
        local out = {}
        local origin = WS:FindFirstChild("_WorldOrigin")
        for _, v in ipairs(childrenOf(origin and origin:FindFirstChild("Locations"))) do
            if v.Name ~= "Sea" then
                table.insert(out, { obj = v, text = "🏝 " .. v.Name, color = Color3.fromRGB(255, 255, 255) })
            end
        end
        return out
    end)

    addCategory("npc", function()
        local out = {}
        for _, v in ipairs(childrenOf(WS:FindFirstChild("NPCs"))) do
            if v:FindFirstChild("HumanoidRootPart") then
                table.insert(out, { obj = v, text = "🧑 " .. v.Name, color = Color3.fromRGB(180, 255, 180) })
            end
        end
        return out
    end)

    addCategory("mob", function()
        local out = {}
        for _, v in ipairs(childrenOf(WS:FindFirstChild("Enemies"))) do
            local hum = v:FindFirstChildOfClass("Humanoid")
            if v:FindFirstChild("HumanoidRootPart") and hum and hum.Health > 0 and not BossSet[v.Name] and not EliteSet[v.Name] then
                table.insert(out, { obj = v, text = v.Name .. " | HP " .. math.floor(hum.Health), color = Color3.fromRGB(255, 160, 80) })
            end
        end
        return out
    end)

    -- Boss: chỉ nhận boss thuộc đúng Sea hiện tại
    addCategory("boss", function()
        local out = {}
        for _, v in ipairs(childrenOf(WS:FindFirstChild("Enemies"))) do
            local hum = v:FindFirstChildOfClass("Humanoid")
            if BossSet[v.Name] and v:FindFirstChild("HumanoidRootPart") and hum and hum.Health > 0 then
                table.insert(out, { obj = v, text = "👑 BOSS: " .. v.Name .. " | HP " .. math.floor(hum.Health), color = Color3.fromRGB(255, 60, 60) })
            end
        end
        return out
    end)

    -- Riêng Sea 2: Hoa (Flower1 = xanh, Flower2 = đỏ)
    addCategory("flower", function()
        local out = {}
        for _, v in ipairs(WS:GetChildren()) do
            if v.Name == "Flower1" then
                table.insert(out, { obj = v, text = "🌸 Hoa Xanh (Blue Flower)", color = Color3.fromRGB(80, 140, 255) })
            elseif v.Name == "Flower2" then
                table.insert(out, { obj = v, text = "🌸 Hoa Đỏ (Red Flower)", color = Color3.fromRGB(255, 70, 70) })
            end
        end
        return out
    end)

    -- Riêng Sea 3: Elite Hunter
    addCategory("elite", function()
        local out = {}
        for _, v in ipairs(childrenOf(WS:FindFirstChild("Enemies"))) do
            local hum = v:FindFirstChildOfClass("Humanoid")
            if EliteSet[v.Name] and v:FindFirstChild("HumanoidRootPart") and hum and hum.Health > 0 then
                table.insert(out, { obj = v, text = "⚔️ ELITE: " .. v.Name, color = Color3.fromRGB(255, 90, 255) })
            end
        end
        return out
    end)

    -- Sea 2 & Sea 3: Sea Beast / sự kiện biển
    addCategory("seaevent", function()
        local out = {}
        for _, v in ipairs(childrenOf(WS:FindFirstChild("SeaBeasts"))) do
            if v:FindFirstChild("HumanoidRootPart") then
                table.insert(out, { obj = v, text = "👑 Sea Beast", color = Color3.fromRGB(0, 240, 255) })
            end
        end
        for _, v in ipairs(childrenOf(WS:FindFirstChild("Enemies"))) do
            local n = v.Name
            if v:FindFirstChild("HumanoidRootPart") then
                if n == "Terrorshark" then
                    table.insert(out, { obj = v, text = "🦈 Terrorshark", color = Color3.fromRGB(255, 60, 60) })
                elseif n == "Shark" then
                    table.insert(out, { obj = v, text = "🐟 Shark", color = Color3.fromRGB(100, 200, 255) })
                elseif n == "Piranha" then
                    table.insert(out, { obj = v, text = "🐡 Piranha", color = Color3.fromRGB(255, 160, 40) })
                elseif n == "Fish Crew Member" or n == "FishBoat" then
                    table.insert(out, { obj = v, text = "🚢 Tàu Cá / Ghost Ship", color = Color3.fromRGB(180, 80, 255) })
                elseif string.find(n, "Brigade") then
                    table.insert(out, { obj = v, text = "⚔️ Tàu Hải Tặc", color = Color3.fromRGB(255, 200, 50) })
                elseif string.find(string.lower(n), "leviathan") then
                    table.insert(out, { obj = v, text = "🐉 Leviathan", color = Color3.fromRGB(0, 255, 180) })
                end
            end
        end
        return out
    end)

    -- Riêng Sea 3: các đảo sự kiện (Mirage / Kitsune / Prehistoric / Frozen Dimension)
    addCategory("specialisland", function()
        local out = {}
        local origin = WS:FindFirstChild("_WorldOrigin")
        for _, v in ipairs(childrenOf(origin and origin:FindFirstChild("Locations"))) do
            if v.Name == "Mirage Island" then
                table.insert(out, { obj = v, text = "🌕 Mirage Island", color = Color3.fromRGB(255, 255, 100) })
            elseif v.Name == "Kitsune Island" then
                table.insert(out, { obj = v, text = "🦊 Kitsune Island", color = Color3.fromRGB(150, 100, 255) })
            elseif v.Name == "PrehistoricIsland" then
                table.insert(out, { obj = v, text = "🦖 Prehistoric Island", color = Color3.fromRGB(255, 170, 60) })
            end
        end
        local map = WS:FindFirstChild("Map")
        if map then
            local mystic = map:FindFirstChild("MysticIsland")
            if mystic then table.insert(out, { obj = mystic, text = "🌕 Mirage Island", color = Color3.fromRGB(255, 255, 100) }) end
            local kitsune = map:FindFirstChild("KitsuneIsland")
            if kitsune then table.insert(out, { obj = kitsune, text = "🦊 Kitsune Island", color = Color3.fromRGB(150, 100, 255) }) end
            local frozen = map:FindFirstChild("FrozenDimension")
            if frozen then table.insert(out, { obj = frozen, text = "❄️ Frozen Dimension", color = Color3.fromRGB(100, 220, 255) }) end
        end
        return out
    end)

    -- ---------- GIAO DIỆN TAB ----------
    local function addToggle(key, title, desc)
        local t = Tab:AddToggle("AbxEsp_" .. key, {
            ["Title"] = title,
            ["Description"] = desc or "",
            ["Default"] = false
        })
        toggles[key] = t
        t:OnChanged(function(v)
            active[key] = (v == true)
            if not active[key] then clearCategory(key) end
        end)
    end

    Tab:AddSection("ESP • " .. SEA_NAME)
    Tab:AddParagraph({
        ["Title"] = "Sea hiện tại",
        ["Description"] = SEA_NAME .. " (tự nhận diện). Tab chỉ hiện các mục có trong Sea này."
    })

    Tab:AddSection("Chung (mọi Sea)")
    addToggle("player", "Người Chơi", "Tên, level và máu người chơi khác")
    addToggle("island", "Đảo", "Tên và khoảng cách các đảo trong Sea hiện tại")
    addToggle("chest", "Rương", "Rương chưa mở")
    addToggle("fruit", "Trái Ác Quỷ", "Trái đang rơi trên map")
    addToggle("realfruit", "Táo / Dứa / Chuối", "Trái cây thật trong map")
    addToggle("npc", "NPC", "Tất cả NPC trong Sea")
    addToggle("mob", "Quái Thường", "Quái trong Sea (không gồm boss)")

    if SEA == 1 then
        Tab:AddSection("Riêng Sea 1")
        addToggle("boss", "Boss Sea 1", "Gorilla King, Bobby, Saw, Yeti, Vice Admiral, Warden, Swan, Magma Admiral, Thunder God, Saber Expert...")
    elseif SEA == 2 then
        Tab:AddSection("Riêng Sea 2")
        addToggle("boss", "Boss Sea 2", "Diamond, Jeremy, Fajita, Don Swan, Smoke Admiral, Cursed Captain, Darkbeard, Order...")
        addToggle("flower", "Hoa (Xanh / Đỏ)", "Nguyên liệu Race V2")
        addToggle("seaevent", "Sea Beast & Sự Kiện Biển", "Sea Beast, cá mập, tàu...")
    elseif SEA == 3 then
        Tab:AddSection("Riêng Sea 3")
        addToggle("boss", "Boss Sea 3", "Stone, Island Empress, Kilo Admiral, Captain Elephant, Longma, Soul Reaper, Cake Queen, Dough King...")
        addToggle("elite", "Elite Hunter", "Diablo, Urban, Deandre")
        addToggle("specialisland", "Đảo Sự Kiện", "Mirage, Kitsune, Prehistoric, Frozen Dimension")
        addToggle("seaevent", "Sea Beast & Sự Kiện Biển", "Sea Beast, Terrorshark, Leviathan, tàu...")
    end

    Tab:AddSection("Tùy Chỉnh")
    Tab:AddSlider("AbxEspDistance", {
        ["Title"] = "Khoảng Cách Tối Đa (studs)",
        ["Min"] = 500,
        ["Max"] = 20000,
        ["Default"] = maxDist,
        ["Callback"] = function(v)
            maxDist = tonumber(v) or maxDist
        end
    })
    Tab:AddButton({
        ["Title"] = "Tắt Tất Cả ESP",
        ["Description"] = "Tắt toàn bộ công tắc và xoá mọi nhãn ESP",
        ["Callback"] = function()
            for key, t in pairs(toggles) do
                active[key] = false
                clearCategory(key)
                pcall(function() t:SetValue(false) end)
            end
        end
    })
end


