_G.AttackOnly = nil
local _tmpl = {}              -- khuôn gói tin theo tên remote
local _inOurCall = false      -- để không học nhầm gói do chính script gửi
local function _desc(v)
    local t = typeof(v)
    if t == "string" then return '"' .. v:sub(1, 40) .. '"' end
    if t == "number" or t == "boolean" then return tostring(v) end
    if t == "Instance" then return v.ClassName .. ":" .. v.Name end
    if t == "table" then return "table(" .. tostring(#v) .. ")" end
    return t
end
pcall(function()
    if not (hookmetamethod and getnamecallmethod) then return end
    local old
    local hook = function(self, ...)
        local m = getnamecallmethod()
        if m == "FireServer" and not _inOurCall and typeof(self) == "Instance" and self.ClassName == "RemoteEvent" then
            local n = self.Name
            if n:find("Register", 1, true) or n:find("Validator", 1, true) then
                local args = table.pack(...)
                if n:find("Register", 1, true) then _tmpl[n] = args end
                if _G.AttackLog then
                    local parts = {}
                    for i = 1, args.n do parts[i] = _desc(args[i]) end
                    print("[AttackLog] " .. n .. "(" .. table.concat(parts, ", ") .. ")")
                end
            end
        end
        return old(self, ...)
    end
    old = hookmetamethod(game, "__namecall", newcclosure and newcclosure(hook) or hook)
end)

-- ===== CLICK THẬT (giống bạn đánh tay) =====
function _realClick()
    local cam = __WS.CurrentCamera
    if not cam then return end
    local vp = cam.ViewportSize
    local x, y = vp.X / 2, vp.Y / 2
    local okVim = pcall(function()
        __VIM:SendMouseButtonEvent(x, y, 0, true, game, 0)
        task.delay(0.04, function()
            pcall(function() __VIM:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
        end)
    end)
    if not okVim then
        pcall(function()
            VirtualUser:CaptureController()
            VirtualUser:Button1Down(Vector2.new(x, y), cam.CFrame)
            task.delay(0.04, function()
                pcall(function() VirtualUser:Button1Up(Vector2.new(x, y), cam.CFrame) end)
            end)
        end)
    end
end

local function _buildArgs(tmpl, part, hits, fallback)
    if not tmpl then return fallback end
    local out = table.pack(table.unpack(tmpl, 1, tmpl.n))
    local usedHits = false
    for i = 1, out.n do
        local a = out[i]
        if typeof(a) == "Instance" and a:IsA("BasePart") then
            out[i] = part
        elseif type(a) == "table" and not usedHits and #a > 0 then
            out[i] = hits
            usedHits = true
        end
    end
    return out
end

local function _fire(remote, args)
    _inOurCall = true
    pcall(function() remote:FireServer(table.unpack(args, 1, args.n)) end)
    _inOurCall = false
end

-- ===== Tìm remote xác thực (có thuộc tính "Id") đi kèm RegisterHit =====
_AtkV = { remote = nil, id = nil }
pcall(function()
    local function scan(folder)
        if not folder then return end
        for _, o in ipairs(folder:GetChildren()) do
            if o:IsA("RemoteEvent") and o:GetAttribute("Id") then
                _AtkV.remote, _AtkV.id = o, o:GetAttribute("Id")
            end
        end
        folder.ChildAdded:Connect(function(o)
            if o:IsA("RemoteEvent") and o:GetAttribute("Id") then
                _AtkV.remote, _AtkV.id = o, o:GetAttribute("Id")
            end
        end)
    end
    for _, n in ipairs({ "Util", "Common", "Remotes", "Assets", "FX" }) do
        scan(__RS:FindFirstChild(n))
    end
end)

-- Gửi đòn đánh: RegisterAttack() + RegisterHit(head, {{mob,part},...}, {}, hash) + remote xác thực
local function _netHit(targets, head)
    local ok = pcall(function()
        local netMod = __RS.Modules.Net
        require(netMod):RemoteEvent("RegisterHit", true)
        netMod["RE/RegisterAttack"]:FireServer()
        netMod["RE/RegisterHit"]:FireServer(head, targets, {},
            tostring(__LP.UserId):sub(2, 4) .. tostring(coroutine.running()):sub(11, 15))
        if _AtkV.remote and _AtkV.id then
            local cr = cloneref or function(x) return x end
            local key = math.floor(workspace:GetServerTimeNow() / 10 % 10) + 1
            local name = string.gsub("RE/RegisterHit", ".", function(c)
                return string.char(bit32.bxor(string.byte(c), key))
            end)
            cr(_AtkV.remote):FireServer(name,
                bit32.bxor(_AtkV.id + 909090, netMod.seed:InvokeServer() * 2), head, targets)
        end
    end)
    return ok
end

local _lastClick, _lastLog = 0, 0

_G.FastAttackEnabled = true
_G.AttackMinInterval = 0.1     -- giãn cách tối thiểu giữa 2 lượt đánh (giây): tránh server chặn vì spam
_G.AttackMaxTargets  = 5       -- tối đa số quái trúng đòn mỗi lượt (gần nhất trước)
_G.AttackStallSeconds = 4      -- quá số giây này đánh mà quái không mất máu => tạm nghỉ + cầm lại vũ khí
_G.AbyAtk = _G.AbyAtk or { busyAt = nil, last = 0, pauseUntil = 0, mob = nil, hp = 0, since = 0, stalls = 0 }
function AttackNoCoolDown()
    if _G.FastAttackEnabled == false then return end
    local _S, _now = _G.AbyAtk, os.clock()
    if _S.busyAt and _now - _S.busyAt < 3 then return end      -- lượt trước còn đang chờ server => không chồng lệnh
    if _now < _S.pauseUntil then return end                     -- đang nghỉ sau khi phát hiện bị đứng đòn
    if _now - _S.last < (_G.AttackMinInterval or 0.1) then return end
    _S.last, _S.busyAt = _now, _now   -- tắt Đánh Nhanh (nút ở tab Cài Đặt)
    local ok, err = pcall(function()
        local char = vu198.Character
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not myRoot or not hum or hum.Health <= 0 then return end
        local myPos = myRoot.Position

        -- tool đang cầm (chưa cầm thì tự cầm rồi đợi lượt sau)
        local tool
        for _, c in ipairs(char:GetChildren()) do
            if c:IsA("Tool") then tool = c break end
        end
        if not tool then
            if SelectWeapon then EquipTool(SelectWeapon) end
            return
        end
        -- Vòng Fast Attack của nhóm tính năng mở rộng đã tự đánh Melee/Sword => không bắn thêm lần nữa
        if _ExtraG and _ExtraG.AutoAttack then
            local _wt = tool:GetAttribute("WeaponType") or tool.ToolTip
            if _wt == "Melee" or _wt == "Sword" then return end
        end

        local enemiesFolder = __WS:FindFirstChild("Enemies")
        if not enemiesFolder then return end

        -- gom quái trong tầm _G.AttackRange studs (chỉnh bằng thanh "Tầm Đánh")
        local hits, firstPart, dirs, firstMob = {}, nil, {}, nil
        local cand = {}
        for _, mob in ipairs(enemiesFolder:GetChildren()) do
            if not mob:GetAttribute("IsBoat") and _alive(mob) then
                local mhrp = mob:FindFirstChild("HumanoidRootPart")
                local part = mob:FindFirstChild("Head") or mhrp
                if mhrp and part then
                    local diff = mhrp.Position - myPos
                    if diff.Magnitude <= (_G.AttackRange or 60) then
                        cand[#cand + 1] = { mob = mob, part = part, diff = diff, mag = diff.Magnitude }
                    end
                end
            end
        end
        table.sort(cand, function(a, b) return a.mag < b.mag end)
        for i = 1, math.min(#cand, _G.AttackMaxTargets or 5) do
            local c = cand[i]
            table.insert(hits, { c.mob, c.part })
            table.insert(dirs, c.mag > 0 and c.diff.Unit or Vector3.new(0, 0, 1))
            firstPart = firstPart or c.part
            firstMob = firstMob or c.mob
        end
        if not firstPart then return end

        -- Phát hiện bị "đứng đòn": đánh liên tục mà quái gần nhất không mất máu => nghỉ ngắn rồi cầm lại vũ khí
        do
            local fh = firstMob:FindFirstChildOfClass("Humanoid")
            if fh then
                local t = os.clock()
                if _S.mob ~= firstMob then
                    _S.mob, _S.hp, _S.since = firstMob, fh.Health, t
                elseif fh.Health < _S.hp then
                    _S.hp, _S.since = fh.Health, t
                elseif t - _S.since > (_G.AttackStallSeconds or 4) then
                    _S.since, _S.pauseUntil, _S.stalls = t, t + 2, _S.stalls + 1
                    pcall(function() hum:UnequipTools() end)
                    if _G.AttackDebug then print("[Attack] đứng đòn lần " .. _S.stalls .. " -> nghỉ 2s, cầm lại vũ khí") end
                    return
                end
            end
        end

        local fired = {}
        local only = _G.AttackOnly   -- [FIX] mặc định nil = dùng TẤT CẢ cách đánh (trước đây "or Click" ép chỉ click thật nên không trúng quái). Muốn ép 1 cách: _G.AttackOnly = "Click" / "RegisterMau" / "LeftClickRemote" / "RegisterMacDinh"

        -- Cách 1: LeftClickRemote (kiểu cũ)
        local lc = tool:FindFirstChild("LeftClickRemote")
        if lc and (not only or only == "LeftClickRemote") then
            for i, dir in ipairs(dirs) do
                _inOurCall = true
                pcall(function() lc:FireServer(dir, i) end)
                _inOurCall = false
            end
            fired[#fired + 1] = "LeftClickRemote"
        end

        -- Cách có xác thực: dùng cho vũ khí Melee/Sword
        local netDone = false
        local wt = tool:GetAttribute("WeaponType") or tool.ToolTip
        if (not only or only == "XacThuc") and (wt == "Melee" or wt == "Sword") then
            local targets = {}
            for _, h in ipairs(hits) do
                targets[#targets + 1] = { h[1], h[1]:FindFirstChild("HumanoidRootPart") or h[2] }
            end
            local head = hits[1] and hits[1][1]:FindFirstChild("Head")
            if head and #targets > 0 then
                _inOurCall = true
                local okR = _netHit(targets, head)
                _inOurCall = false
                if okR then netDone = true; fired[#fired + 1] = "XacThuc" end
            end
        end

        -- Cách 2: RegisterAttack + RegisterHit, ưu tiên dùng khuôn học từ đòn đánh tay của bạn
        local mods = __RS:FindFirstChild("Modules")
        local net  = mods and mods:FindFirstChild("Net")
        local reAtk = net and net:FindFirstChild("RE/RegisterAttack")
        local reHit = net and net:FindFirstChild("RE/RegisterHit")
        if reAtk and reHit and not netDone then
            local useTmpl = _tmpl["RE/RegisterHit"] ~= nil
            if (not only) or (only == "RegisterMau" and useTmpl) or (only == "RegisterMacDinh") then
                local tA = (only ~= "RegisterMacDinh") and _tmpl["RE/RegisterAttack"] or nil
                local tH = (only ~= "RegisterMacDinh") and _tmpl["RE/RegisterHit"] or nil
                _fire(reAtk, _buildArgs(tA, firstPart, hits, table.pack(0)))
                _fire(reHit, _buildArgs(tH, firstPart, hits, table.pack(firstPart, hits, {}, string.sub(tostring(__LP.UserId), 2, 4) .. string.sub(tostring(coroutine.running()), 11, 15))))
                fired[#fired + 1] = tH and "RegisterHit(khuôn học)" or "RegisterHit(mặc định)"
            end
        end

        -- [ĐÃ XÓA] Cách 3: click thật (gây vung tay). Chỉ còn đánh bằng remote.

        if _G.AttackDebug and os.clock() - _lastLog > 1 then
            _lastLog = os.clock()
            local h = firstMob and firstMob:FindFirstChildOfClass("Humanoid")
            print(("[Attack] tool=%s | quái=%d | máu quái đầu=%s | dùng: %s | đã học khuôn: %s"):format(
                tool.Name, #hits, h and tostring(math.floor(h.Health)) or "?", table.concat(fired, ", "),
                tostring(_tmpl["RE/RegisterHit"] ~= nil)))
        end
    end)
    _S.busyAt = nil
    if not ok then warn("[AttackNoCoolDown] " .. tostring(err)) end
end
-- ===== TỰ KIỂM TRA: cách đánh nào thật sự làm quái mất máu =====
-- Cách dùng: đứng cạnh 1 con quái (đang cầm vũ khí), gõ trong executor:  _G.AttackTest()
-- Script thử từng cách 2 giây, in ra lượng máu quái mất, rồi tự chọn cách mạnh nhất.
function _G.AttackTest(autoPick)
    task.spawn(function()
        local char = __LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local en = __WS:FindFirstChild("Enemies")
        if not root or not en then print("[AttackTest] chưa có nhân vật/quái") return end
        local target
        for _, m in ipairs(en:GetChildren()) do
            local h, r = m:FindFirstChildOfClass("Humanoid"), m:FindFirstChild("HumanoidRootPart")
            if h and r and h.Health > 0 and (r.Position - root.Position).Magnitude <= 50 then target = m break end
        end
        if not target then print("[AttackTest] không có quái nào trong 50 studs, hãy đứng gần quái hơn") return end
        local hum = target:FindFirstChildOfClass("Humanoid")
        local keepOnly = _G.AttackOnly
        local best, bestDrop = nil, 0
        for _, mode in ipairs({ "LeftClickRemote", "RegisterMau", "RegisterMacDinh" }) do
            if not target.Parent or hum.Health <= 0 then print("[AttackTest] quái đã chết, dừng") break end
            _G.AttackOnly = mode
            local before = hum.Health
            local t0 = os.clock()
            while os.clock() - t0 < 2 and hum.Health > 0 do
                AttackNoCoolDown()
                task.wait(0.05)
            end
            local drop = before - hum.Health
            print(("[AttackTest] %-16s -> quái mất %d máu trong 2 giây"):format(mode, math.floor(drop)))
            if drop > bestDrop then best, bestDrop = mode, drop end
            task.wait(0.5)
        end
        _G.AttackOnly = keepOnly
        if best and autoPick ~= false then
            _G.AttackOnly = best
            print("[AttackTest] Đã tự chọn cách mạnh nhất: " .. best .. "  (muốn dùng lại tất cả: _G.AttackOnly = nil)")
        elseif not best then
            print("[AttackTest] Không cách nào làm quái mất máu, gửi mình các dòng này để mình xem tiếp")
        end
    end)
end

-- ===== [THÊM THEO YÊU CẦU] Quét Hitbox 100 studs (bật/tắt bằng nút "Đánh Nhanh") =====
-- Bọc trong do...end để không tạo thêm biến local ở cấp file (Lua giới hạn 200 local mỗi chunk)
do
    local Workspace = game:GetService("Workspace")
    local Players = game:GetService("Players")
    local localPlayer = Players.LocalPlayer

    local function CheckMaxRangeHitbox()
        local character = localPlayer.Character
        if not character or not character:FindFirstChild("HumanoidRootPart") then return end

        local rootPart = character.HumanoidRootPart

        -- Đặt kích thước Hitbox tối đa 100 studs (Rộng: 10, Cao/Dài: 100)
        local maxRange = 100
        local boxSize = Vector3.new(10, maxRange, 10)

        -- Tâm hộp cách nhân vật maxRange / 2 để vùng quét vươn lên tới 100 studs
        local boxCFrame = rootPart.CFrame * CFrame.new(0, maxRange / 2, 0)

        -- Loại trừ chính nhân vật ra khỏi vùng quét
        local overlapParams = OverlapParams.new()
        overlapParams.FilterDescendantsInstances = {character}
        overlapParams.FilterType = Enum.RaycastFilterType.Exclude

        local partsInBox = Workspace:GetPartBoundsInBox(boxCFrame, boxSize, overlapParams)

        local hitEnemies = {}

        for _, part in ipairs(partsInBox) do
            local model = part.Parent
            local humanoid = model and model:FindFirstChildOfClass("Humanoid")

            if humanoid and humanoid.Health > 0 and not hitEnemies[model] then
                hitEnemies[model] = true

                -- Lưu ý: TakeDamage chạy phía client nên server không ghi nhận sát thương thật
                humanoid:TakeDamage(30)
                print("Đã đánh trúng mục tiêu trong tầm 100 studs: " .. model.Name)
            end
        end
    end

    -- Chỉ chạy khi bật nút "Đánh Nhanh" (_G.OneHitKill)
    task.spawn(function()
        while task.wait(0.2) do
            if _G.OneHitKill then
                pcall(CheckMaxRangeHitbox)
            end
        end
    end)
end

