-- [FIX ĐỨNG IM SAU KHI NHẬN QUEST] theo dõi số lần đã nhận quest, phòng khi UI Quest không báo Visible
local _qKey, _qTries, _qStart = nil, 0, 0
local _lastAbandon = 0
spawn(function()
    while task.wait() do
        if _G.AutoLevel then
            local __ok, __err = pcall(function()
                CheckLevel()

                if not Ms or not NameMon or not NameQuest or not QuestLv or not CFrameQ or not CFrameMon then
                    return
                end

                local questVisible = false
                local QuestTitle = ""
                pcall(function() questVisible = __LP.PlayerGui.Main.Quest.Visible end)
                pcall(function()
                    if questVisible then
                        QuestTitle = __LP.PlayerGui.Main.Quest.Container.QuestTitle.Title.Text
                    end
                end)
                -- [FIX] đọc title lỗi => coi như đúng quest; cắt 2 ký tự cuối để khớp số nhiều (Snowman/Snowmen)
                local titleOK = QuestTitle == "" or string.find(QuestTitle:lower(), NameMon:lower():sub(1, -3), 1, true) ~= nil

                -- [FIX] Quest đã nhận (StartQuest chạy >= 2 lần) mà UI vẫn không báo Visible
                -- => coi như quest đang chạy và đi farm, không đứng lại NPC gọi StartQuest mãi
                local _key = tostring(NameQuest) .. "|" .. tostring(QuestLv)
                if _qKey ~= _key then _qKey = _key; _qTries = 0 end
                if questVisible then _qTries = 0 end
                if not questVisible and _qTries >= 2 then
                    if os.clock() - _qStart < 90 then
                        questVisible = true
                        titleOK = true
                    else
                        _qTries = 0   -- quá 90s thì thử nhận lại quest mới
                    end
                end
                if _G.FarmDebug then
                    print(("[Farm] quest=%s lv=%s visible=%s titleOK=%s tries=%d mob=%s"):format(
                        tostring(NameQuest), tostring(QuestLv), tostring(questVisible), tostring(titleOK), _qTries, tostring(Ms)))
                end

                -- [FIX] quest do chính script vừa nhận (trong 90s) => tin là đúng, tránh vòng lặp Abandon -> Start -> Abandon
                if questVisible and _qTries >= 1 and os.clock() - _qStart < 90 then
                    titleOK = true
                end

                -- Nếu đang có quest KHÁC thì bỏ quest (có cooldown, không spam remote)
                if questVisible and not titleOK then
                    bringmob = false
                    if os.clock() - _lastAbandon > 3 then
                        _lastAbandon = os.clock()
                        __RS.Remotes.CommF_:InvokeServer("AbandonQuest")
                        _qTries = 0
                        task.wait(0.5)
                    end
                    return
                end

                -- Chưa có quest → bay tới NPC nhận quest bằng Tween2 (giống di chuyển đảo)
                if not questVisible then
                    bringmob = false
                    Tween2(CFrameQ)
                    local _t0 = os.clock()
                    repeat task.wait(0.1) until (CFrameQ.Position - __LP.Character.HumanoidRootPart.Position).Magnitude <= 20 or not _G.AutoLevel or not MoverBusy() or os.clock() - _t0 > 10
                    wait(0.2)
                    if (CFrameQ.Position - __LP.Character.HumanoidRootPart.Position).Magnitude <= 20 then
                        __RS.Remotes.CommF_:InvokeServer("StartQuest", NameQuest, QuestLv)
                        _qTries = _qTries + 1
                        _qStart = os.clock()
                        wait(0.3)
                    end
                    return
                end

                -- Đã có quest đúng → farm (dùng BKP để đứng cạnh quái, giống island travel)
                if questVisible and titleOK then
                    local _foundAlive = false
                    if __WS.Enemies:FindFirstChild(Ms) then
                        for _, v in pairs(__WS.Enemies:GetChildren()) do
                            if v:FindFirstChild("Humanoid") and v:FindFirstChild("HumanoidRootPart") and v.Humanoid.Health > 0 and v.Name == Ms then
                                _foundAlive = true
                                -- Bật hiệu ứng tia lửa + tiếng spam liên tục
                                if not _fxEnabled then _fxEnabled = true; StartFXLoop() end
                                repeat
                                    task.wait(_G.Fast_Delay)
                                    AttackNoCoolDown()
                                    bringmob = true
                                    AutoHaki()
                                    EquipTool(SelectWeapon)
                                    -- Dùng BKP teleport trực tiếp cạnh quái (giống các tính năng khác)
                                    if MoverBusy() then StopMovement() end   -- [FIX] mover cũ không được kéo ngược khi đang bám quái
                                    local _mobCF = v.HumanoidRootPart.CFrame * Pos
                                    if (_mobCF.Position - __LP.Character.HumanoidRootPart.Position).Magnitude > 5 then
                                        BKP(_mobCF)
                                    end
                                    -- [OPT] chỉ ghi property khi giá trị đang khác (tránh ghi lại mỗi frame)
                                    local mhrp, mhum = v.HumanoidRootPart, v.Humanoid
                                    if mhrp.Size ~= _MOB_BIG then mhrp.Size = _MOB_BIG end
                                    if mhrp.Transparency ~= 1 then mhrp.Transparency = 1 end
                                    if mhum.JumpPower ~= 0 then mhum.JumpPower = 0 end
                                    if mhum.WalkSpeed ~= 0 then mhum.WalkSpeed = 0 end
                                    if mhrp.CanCollide then mhrp.CanCollide = false end
                                    local mhead = v:FindFirstChild("Head")
                                    if mhead and mhead.CanCollide then mhead.CanCollide = false end
                                    FarmPos = v.HumanoidRootPart.CFrame
                                    MonFarm = v.Name
                                    -- [OPT] không tạo closure + pcall mỗi frame
                                    local qv = (_qTries >= 2)
                                    local _mg = __LP.PlayerGui:FindFirstChild("Main")
                                    local _qg = _mg and _mg:FindFirstChild("Quest")
                                    if _qg and _qg.Visible then qv = true end
                                until not _G.AutoLevel or not v.Parent or v.Humanoid.Health <= 0 or not qv
                                bringmob = false
                                if not _G.OneHitKill and not _G.AutoBone and not BoneNoQuestOn() and not _G.AutoNear then StopFXLoop() end
                            end
                        end
                    end
                    if not _foundAlive then
                        bringmob = false
                        -- Bay đến vị trí quái spawn bằng Tween2 (giống di chuyển đảo)
                        Tween2(CFrameMon)
                    end
                end
            end)
            if not __ok then warn("[AutoLevel]", __err) end
        end
    end
end)
