_fxThread = nil      -- coroutine vòng lặp hiệu ứng
_fxEnabled = false   -- bật/tắt hiệu ứng

-- Danh sách sound IDs tiếng đánh (ngắn, mạnh, đa dạng)
local _hitSounds = {
