-- [OPT] Hiệu ứng đóm: trước tạo ~80 Part + Sparkles + ParticleEmitter mỗi lần (~1300 instance/giây).
-- Nay: dùng 1 template ParticleEmitter (Clone), 1 Part/lần, tính vùng bao bằng GetBoundingBox,
-- phát vài emitter rải trong vùng bao -> số instance giảm ~15 lần, hình ảnh gần như giữ nguyên.
local _Debris = game:GetService("Debris")
local _sparkTemplate = Instance.new("ParticleEmitter")
_sparkTemplate.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0,    Color3.fromRGB(255, 255, 255)),
    ColorSequenceKeypoint.new(0.2,  Color3.fromRGB(255, 240, 120)),
    ColorSequenceKeypoint.new(0.55, Color3.fromRGB(255, 140, 0)),
    ColorSequenceKeypoint.new(1,    Color3.fromRGB(220, 30, 0)),
})
_sparkTemplate.LightEmission  = 1
_sparkTemplate.LightInfluence = 0
_sparkTemplate.Size = NumberSequence.new({
    NumberSequenceKeypoint.new(0,   0.55),
    NumberSequenceKeypoint.new(0.4, 0.35),
    NumberSequenceKeypoint.new(1,   0),
})
_sparkTemplate.Transparency = NumberSequence.new({
    NumberSequenceKeypoint.new(0,   0),
    NumberSequenceKeypoint.new(0.6, 0.3),
    NumberSequenceKeypoint.new(1,   1),
})
_sparkTemplate.Speed       = NumberRange.new(6, 18)
_sparkTemplate.SpreadAngle = Vector2.new(180, 180)
_sparkTemplate.Rate        = 0
_sparkTemplate.Lifetime    = NumberRange.new(0.25, 0.65)
_sparkTemplate.RotSpeed    = NumberRange.new(-400, 400)
_sparkTemplate.Rotation    = NumberRange.new(0, 360)

local FX_NODES = 6 -- số điểm phát đóm trên mỗi quái
local function SpawnSparkFX(mob)
    do return end -- [ĐÃ TẮT] hiệu ứng pháo hoa
    pcall(function()
        if not mob or not mob.Parent then return end
        local cf, size = mob:GetBoundingBox()
        local half = size * 0.5 + Vector3.new(2, 2, 2)
        local holder = Instance.new("Part")
        holder.Anchored = true
        holder.CanCollide = false
        holder.CanQuery = false
        holder.CanTouch = false
        holder.CastShadow = false
        holder.Transparency = 1
        holder.Size = Vector3.new(0.1, 0.1, 0.1)
        holder.CFrame = cf
        for _ = 1, FX_NODES do
            local att = Instance.new("Attachment")
            att.Position = Vector3.new(
                (math.random() * 2 - 1) * half.X,
                (math.random() * 2 - 1) * half.Y,
                (math.random() * 2 - 1) * half.Z)
            att.Parent = holder
            local pe = _sparkTemplate:Clone()
            pe.Parent = att
            pe:Emit(math.random(40, 70))
        end
        holder.Parent = workspace
        _Debris:AddItem(holder, 0.7)
    end)
end

-- Phát tiếng đánh ngẫu nhiên tại vị trí
local function PlayHitSound(pos)
    do return end -- [ĐÃ TẮT] tiếng đánh
    pcall(function()
        local sid = _hitSounds[math.random(1, #_hitSounds)]
        local snd = Instance.new("Sound")
        snd.SoundId = sid
        snd.Volume = 0.9
        snd.RollOffMaxDistance = 60
        local p = Instance.new("Part")
        p.Anchored = true; p.CanCollide = false
        p.Transparency = 1; p.Size = Vector3.new(0.1,0.1,0.1)
        p.Position = pos; p.Parent = workspace
        snd.Parent = p
        snd:Play()
        game:GetService("Debris"):AddItem(p, 1.5)
    end)
end

-- Giữ tên cũ để code bên dưới dùng được
local function ApplyHitEffect(mob)
    SpawnSparkFX(mob)
end

-- Vòng lặp hiệu ứng chính: spam đóm + tiếng mỗi 0.06s (~17 lần/giây)
local _fxLastHp = setmetatable({}, {__mode = "k"})
function StartFXLoop()
    do return end -- [ĐÃ TẮT] vòng lặp hiệu ứng
    if _fxThread then pcall(function() task.cancel(_fxThread) end) end
    _fxThread = task.spawn(function()
        while _fxEnabled do
            pcall(function()
                if MonFarm and MonFarm ~= "" then
                    for _, mob in pairs(__WS.Enemies:GetChildren()) do
                        if mob.Name == MonFarm
                            and mob:FindFirstChild("HumanoidRootPart")
                            and mob:FindFirstChild("Humanoid")
                            and mob.Humanoid.Health > 0 then
                            local pos = mob.HumanoidRootPart.Position
                            local hp = mob.Humanoid.Health
                            if _fxLastHp[mob] and hp < _fxLastHp[mob] then
                                SpawnSparkFX(mob)
                                PlayHitSound(pos)
                            end
                            _fxLastHp[mob] = hp
                            break
                        end
                    end
                end
            end)
            task.wait(0.12) -- [OPT] 0.06 -> 0.12s (đóm đã được gom nên không bị thưa)
        end
        _fxThread = nil
    end)
end

function StopFXLoop()
    _fxEnabled = false
    if _fxThread then
        pcall(function() task.cancel(_fxThread) end)
        _fxThread = nil
    end
end

-- ============================================================
-- ĐÁNH NHANH: HP quái còn 25%, tự động kích hoạt hiệu ứng
-- ============================================================
local _oneHitConns = {}

-- [OPT] Handler HealthChanged gọn: không pcall/closure, không gọi sethiddenproperty mỗi lần đổi máu,
-- bỏ biến prevHp không dùng; sethiddenproperty chỉ gọi 1 lần mỗi nhịp thay vì cho từng quái.
-- [ĐÃ BỎ] Trước đây hàm này tự ghi Humanoid.Health của quái xuống 25% NGAY TRÊN MÁY BẠN.
-- Server không hề nhận sát thương nên quái chỉ "trông như" mất máu: không hiện số damage,
-- quest không tính kill, quái không chết thật. Giờ không ghi máu quái nữa, mọi sát thương phải là thật.
local function _hookMobHp(mob, hum) end

spawn(function()
    while wait(0.1) do
        if _G.OneHitKill then
            -- Bật FX loop khi đánh nhanh đang on
            if not _fxEnabled then
                _fxEnabled = true
                StartFXLoop()
            end
            pcall(function()
                pcall(sethiddenproperty, __LP, "SimulationRadius", math.huge)
                for _, mob in ipairs(__WS.Enemies:GetChildren()) do
                    -- (không còn hạ máu quái ở phía client)
                end
                -- Dọn connection mob đã despawn
                for mob, conn in pairs(_oneHitConns) do
                    if not mob.Parent then
                        conn:Disconnect()
                        _oneHitConns[mob] = nil
                    end
                end
            end)
        else
            -- Tắt FX loop khi OneHitKill off
            if _fxEnabled and not (_G.AutoBone or BoneNoQuestOn() or _G.AutoLevel or _G.AutoNear) then
                StopFXLoop()
            end
            if next(_oneHitConns) then
                for _, conn in pairs(_oneHitConns) do conn:Disconnect() end
                _oneHitConns = {}
            end
        end
    end
end)
