-- ======================================================================
-- [NEW] Helper dùng chung cho Cày Xương / Cày Tư Lệnh Bánh (chế độ CÓ nhiệm vụ)
-- ======================================================================
local CAKE_MOBS = {["Cookie Crafter"] = true, ["Cake Guard"] = true, ["Baking Staff"] = true, ["Head Baker"] = true}

-- trả về: đang hiện quest?, tiêu đề quest
local function GetQuestGui()
    local main = __LP.PlayerGui:FindFirstChild("Main")
    local q = main and main:FindFirstChild("Quest")
    if not q or not q.Visible then return false, "" end
    local ok, t = pcall(function() return q.Container.QuestTitle.Title.Text end)
    return true, (ok and t) or ""
end

-- bay tới NPC rồi nhận quest. flagFn(): còn bật chức năng không
local function TakeQuest(qCF, qName, qLv, flagFn)
    Tween2(qCF)
    repeat task.wait(0.1) until (qCF.Position - __LP.Character.HumanoidRootPart.Position).Magnitude <= 20 or not flagFn() or not MoverBusy()
    wait(0.2)
    if (qCF.Position - __LP.Character.HumanoidRootPart.Position).Magnitude <= 20 then
        __RS.Remotes.CommF_:InvokeServer("StartQuest", qName, qLv)
        wait(0.3)
    end
end

-- =====================================================================
-- [FIX] Nhận nhiệm vụ cho Cày Xương / Cày Tư Lệnh Bánh (có nhiệm vụ)
-- Dùng cùng cơ chế đã vá sẵn ở Auto Level. Lỗi cũ:
--  1) So tên quái bằng string.find nguyên tên: quest "Posessed Mummy" hiện là "Defeat ... Posessed Mummies"
--     => không khớp => script tưởng sai quest, AbandonQuest rồi nhận lại liên tục (kẹt ở NPC).
--  2) Không có cooldown cho AbandonQuest (spam remote), không chịu được lúc title chưa đọc được.
--  3) UI quest không báo Visible dù đã nhận => đứng lại NPC gọi StartQuest mãi.
-- Cách sửa: khớp theo thân từ (cắt 2 ký tự cuối), title rỗng coi là đúng, abandon có cooldown 3s,
-- đã StartQuest >= 2 lần mà UI chưa báo thì coi như đang chạy (tối đa 90s), bay tới NPC tối đa 10s.
-- Dùng bảng global AbyQuest (không thêm biến local vào scope chính).
-- =====================================================================
AbyQuest = { state = {} }

function AbyQuest.Get(id)
    local st = AbyQuest.state[id]
    if not st then
        st = { key = "", tries = 0, start = 0, lastAbandon = 0 }
        AbyQuest.state[id] = st
    end
    return st
end

function AbyQuest.TitleOK(title, mob)
    if not title or title == "" then return true end
    return string.find(string.lower(title), string.sub(string.lower(mob), 1, -3), 1, true) ~= nil
end

-- true nếu quest đang chạy (UI báo Visible, hoặc vừa nhận >= 2 lần trong 90s mà UI chưa cập nhật)
function AbyQuest.Active(id)
    local vis = GetQuestGui()
    if vis then return true end
    local st = AbyQuest.Get(id)
    return st.tries >= 2 and os.clock() - st.start < 90
end

-- true = đã có đúng quest, đi farm được; false = vừa xử lý quest (nhận/bỏ), caller nên return
function AbyQuest.Ensure(id, qName, qLv, qMob, qCF, flagFn)
    local st = AbyQuest.Get(id)
    local key = qName .. "|" .. tostring(qLv)
    if st.key ~= key then st.key = key; st.tries = 0; st.start = 0 end

    local vis, title = GetQuestGui()
    if vis then
        if AbyQuest.TitleOK(title, qMob) then
            st.tries = 0
            return true
        end
        -- đang giữ quest KHÁC (hoặc title chưa kịp đổi sau khi vừa nhận): chờ 4s đầu rồi mới bỏ
        bringmob = false
        if os.clock() - st.start < 4 then task.wait(0.3); return false end
        if os.clock() - st.lastAbandon > 3 then
            st.lastAbandon = os.clock()
            __RS.Remotes.CommF_:InvokeServer("AbandonQuest")
            st.tries = 0
            task.wait(0.5)
        end
        return false
    end

    -- UI không báo Visible nhưng đã StartQuest >= 2 lần => coi như đang chạy
    if st.tries >= 2 then
        if os.clock() - st.start < 90 then return true end
        st.tries = 0 -- quá 90s: thử nhận lại
    end

    bringmob = false
    Tween2(qCF)
    local t0 = os.clock()
    repeat
        task.wait(0.1)
    until (qCF.Position - __LP.Character.HumanoidRootPart.Position).Magnitude <= 20
        or not flagFn() or not MoverBusy() or os.clock() - t0 > 10
    task.wait(0.2)
    if flagFn() and (qCF.Position - __LP.Character.HumanoidRootPart.Position).Magnitude <= 20 then
        -- [FIX 2-3 LẦN MỚI NHẬN] chờ server cập nhật vị trí rồi mới gọi StartQuest,
        -- gọi xong thì CHỜ UI Quest hiện để xác nhận (thay vì đếm 'tries' mù quáng như trước)
        task.wait(0.5)
        for _ = 1, 3 do
            if not flagFn() then return false end
            pcall(function()
                local hrp = __LP.Character.HumanoidRootPart
                hrp.CFrame = qCF -- giữ sát NPC
                hrp.AssemblyLinearVelocity = Vector3.zero
            end)
            __RS.Remotes.CommF_:InvokeServer("StartQuest", qName, qLv)
            local t1 = os.clock()
            repeat task.wait(0.1) until (GetQuestGui()) or os.clock() - t1 > 1.2 or not flagFn()
            if GetQuestGui() then
                st.tries = 0
                st.start = os.clock()
                return false -- vòng sau thấy UI + đúng title => đi farm
            end
        end
        -- 3 lần mà UI vẫn không báo: dùng fallback cũ (coi như đã nhận, tối đa 90s)
        st.tries = 2
        st.start = os.clock()
    end
    return false
end

local QUEST_HAUNTED1 = CFrame.new(-9480.80762, 142.130661, 5566.37305)
local QUEST_HAUNTED2 = CFrame.new(-9516.9931640625, 178.00651550293, 6078.4653320313)
-- dữ liệu quest xương theo cấp (khớp bảng CheckLevel). Dưới cấp 1975 → nil (farm không quest)
local function GetBoneQuest()
    local lv = __LP.Data.Level.Value
    if lv < 1975 then return nil end
    if lv < 2000 then return "HauntedQuest1", 1, "Reborn Skeleton", QUEST_HAUNTED1 end
    if lv < 2025 then return "HauntedQuest1", 2, "Living Zombie", QUEST_HAUNTED1 end
    if lv < 2050 then return "HauntedQuest2", 1, "Demonic Soul", QUEST_HAUNTED2 end
    return "HauntedQuest2", 2, "Posessed Mummy", QUEST_HAUNTED2
end

local QUEST_CAKE1 = CFrame.new(-2022.29858, 36.9275894, -12030.9766)
local QUEST_CAKE2 = CFrame.new(-1928.31763, 37.7296638, -12840.626)
-- dữ liệu quest Cake theo cấp. Dưới cấp 2200 → nil (farm không quest)
local function GetCakeQuest()
    local lv = __LP.Data.Level.Value
    if lv < 2200 then return nil end
    if lv < 2225 then return "CakeQuest1", 1, "Cookie Crafter", QUEST_CAKE1 end
    if lv < 2250 then return "CakeQuest1", 2, "Cake Guard", QUEST_CAKE1 end
    if lv < 2275 then return "CakeQuest2", 1, "Baking Staff", QUEST_CAKE2 end
    return "CakeQuest2", 2, "Head Baker", QUEST_CAKE2
end

