-- ==========================================
-- [TAB RAID BOSS] Trạng thái boss, thông báo, bay tới boss, tự đánh boss đã chọn, đổi server tìm boss
-- ==========================================
do
    local BOSSES = {
        { "rip_indra", "Rip Indra" }, { "Dough King", "Dough King" }, { "Cake Prince", "Cake Prince" },
        { "Cake Queen", "Cake Queen" }, { "Darkbeard", "Darkbeard" }, { "Order", "Order" },
        { "Soul Reaper", "Soul Reaper" }, { "Tyrant of the Skies", "Tyrant of the Skies" },
        { "Cursed Captain", "Cursed Captain" }, { "Greybeard", "Greybeard" }, { "Don Swan", "Don Swan" },
        { "Smoke Admiral", "Smoke Admiral" }, { "Diamond", "Diamond" }, { "Fajita", "Fajita" },
        { "Thunder God", "Thunder God" }, { "Mob Leader", "Mob Leader" }, { "Chief Warden", "Chief Warden" },
        { "Longma", "Longma" }, { "Beautiful Pirate", "Beautiful Pirate" }, { "Captain Elephant", "Captain Elephant" },
        { "Stone", "Stone" }, { "Kilo Admiral", "Kilo Admiral" }, { "Diablo", "Diablo" },
        { "Deandre", "Deandre" }, { "Urban", "Urban" },
    }
    local LABELS, NAME_OF = {}, {}
    for _, b in ipairs(BOSSES) do table.insert(LABELS, b[2]); NAME_OF[b[2]] = b[1] end
    local selected = BOSSES[1][1]

    local function findBoss(name)
        local en = __WS:FindFirstChild("Enemies")
        local b = en and en:FindFirstChild(name)
        if b and b:FindFirstChild("Humanoid") and b:FindFirstChild("HumanoidRootPart") and b.Humanoid.Health > 0 then
            return b
        end
    end
    local function notify(msg)
        pcall(function() Library:Notify({["Title"] = "Raid Boss", ["Content"] = msg}) end)
    end

    -- Vị trí của boss: nếu đang xuất hiện thì lấy vị trí thật, nếu chưa thì lấy điểm spawn
    local function bossSpawnCF(name)
        local alive = findBoss(name)
        if alive then return alive.HumanoidRootPart.CFrame end
        local tpl = __RS:FindFirstChild(name)
        local thrp = tpl and tpl:FindFirstChild("HumanoidRootPart")
        if thrp then return thrp.CFrame end
        local wo = __WS:FindFirstChild("_WorldOrigin")
        local es = wo and wo:FindFirstChild("EnemySpawns")
        if es then
            for _, p in ipairs(es:GetChildren()) do
                if p:IsA("BasePart") and (p.Name == name or string.find(p.Name, name, 1, true)) then
                    return p.CFrame
                end
            end
        end
        return nil
    end

    Tabs.Boss:AddSection("Chọn Boss")
    Tabs.Boss:AddDropdown("BossSelectDropdown", {
        ["Title"] = "Chọn Boss",
        ["Values"] = LABELS,
        ["Multi"] = false,
        ["Default"] = 1
    }):OnChanged(function(v) selected = NAME_OF[v] or selected end)
    Tabs.Boss:AddButton({["Title"] = "Bay Đến Boss Đã Chọn", ["Description"] = "Bay tới boss đang xuất hiện, nếu chưa có thì bay tới điểm spawn của boss", ["Callback"] = function()
        task.spawn(function()
            local cf = bossSpawnCF(selected)
            if cf then
                Tween2(cf * CFrame.new(0, 40, 0))
            else
                notify("Không tìm thấy vị trí của boss này")
            end
        end)
    end})
    _G.BossKill = false
    Tabs.Boss:AddToggle("BossKillToggle", {
        ["Title"] = "Tự Đánh Boss Đã Chọn",
        ["Description"] = "Tự bay tới điểm spawn của boss đã chọn, boss xuất hiện thì đánh đến khi chết",
        ["Default"] = false
    }):OnChanged(function(v) _G.BossKill = v end)
    spawn(function()
        while task.wait(0.2) do
            if _G.BossKill then
                pcall(function()
                    local boss = findBoss(selected)
                    if not boss then
                        local cf = bossSpawnCF(selected)
                        local root = __LP.Character and __LP.Character:FindFirstChild("HumanoidRootPart")
                        if cf and root and (root.Position - cf.Position).Magnitude > 150 then
                            Tween2(cf * CFrame.new(0, 60, 0))
                        end
                        return
                    end
                    local hrp, hum = boss.HumanoidRootPart, boss.Humanoid
                    repeat
                        task.wait(_G.Fast_Delay or 0.05)
                        AttackNoCoolDown()
                        AutoHaki()
                        EquipTool(SelectWeapon)
                        hrp.CanCollide = false
                        Tween2(hrp.CFrame * (Pos or CFrame.new(0, 30, 0)))
                    until not _G.BossKill or not boss.Parent or hum.Health <= 0
                end)
            end
        end
    end)

    Tabs.Boss:AddSection("Đổi Server Tìm Boss")
    _G.BossHopFind = false
    Tabs.Boss:AddToggle("BossHopFindToggle", {
        ["Title"] = "Tự Đổi Server Đến Khi Có Boss Đã Chọn",
        ["Description"] = "Gặp boss thì dừng đổi server. Để script trong autoexec để tự chạy lại sau mỗi lần đổi server.",
        ["Default"] = false
    }):OnChanged(function(v) _G.BossHopFind = v end)
    spawn(function()
        local startAt, lastHop = tick(), 0
        while task.wait(3) do
            if _G.BossHopFind and _G.AbyLoaded and tick() - startAt > 20 then
                pcall(function()
                    if findBoss(selected) then
                        if tick() - lastHop > 30 then lastHop = tick(); notify("Đã thấy boss - dừng đổi server") end
                        return
                    end
                    if tick() - lastHop < 25 then return end
                    lastHop = tick()
                    local data = HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&limit=100"))
                    local list = {}
                    for _, v in ipairs(data.data or {}) do
                        if v.id ~= game.JobId and v.playing < v.maxPlayers then table.insert(list, v) end
                    end
                    if #list > 0 then
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, list[math.random(1, #list)].id, __LP)
                    end
                end)
            end
        end
    end)

    Tabs.Boss:AddSection("Tự Kích Hoạt (Triệu Hồi) Boss")

    -- Cake Prince: dùng lại cờ có sẵn _G.SpawnCakePrince (vòng lặp triệu hồi đã có trong script)
    Tabs.Boss:AddToggle("ToggleSpawnCake", {
        ["Title"] = "Triệu Hồi Cake Prince (Tư Lệnh Bánh)",
        ["Description"] = "Tự gửi lệnh triệu hồi khi đủ điều kiện (Sea 3)",
        ["Default"] = true
    }):OnChanged(function(v) _G.SpawnCakePrince = v end)

    -- Elite (Diablo / Deandre / Urban): nhận Elite Hunter để boss xuất hiện
    _G.BossSummonElite = false
    Tabs.Boss:AddToggle("BossSummonEliteToggle", {
        ["Title"] = "Tự Kích Hoạt Elite (Diablo / Deandre / Urban)",
        ["Description"] = "Tự nhận Elite Hunter để Elite boss xuất hiện. Dùng cùng 'Tự Đánh Boss Đã Chọn' để tự đánh.",
        ["Default"] = false
    }):OnChanged(function(v) _G.BossSummonElite = v end)
    spawn(function()
        while task.wait(2) do
            if _G.BossSummonElite then
                pcall(function()
                    if findBoss("Diablo") or findBoss("Deandre") or findBoss("Urban") then return end
                    if __LP.PlayerGui.Main.Quest.Visible ~= true then
                        __RS.Remotes.CommF_:InvokeServer("EliteHunter")
                    end
                end)
            end
        end
    end)

    -- Soul Reaper: có Hallow Essence thì bay tới Lâu Đài Ma và cầm Hallow Essence để gọi boss
    _G.BossSummonSoul = false
    Tabs.Boss:AddToggle("BossSummonSoulToggle", {
        ["Title"] = "Tự Triệu Hồi Soul Reaper (Hallow Essence)",
        ["Description"] = "Cần có sẵn Hallow Essence trong túi. Tự bay tới điểm triệu hồi rồi cầm vật phẩm.",
        ["Default"] = false
    }):OnChanged(function(v) _G.BossSummonSoul = v end)
    spawn(function()
        local spot = CFrame.new(-8932.322265625, 146.83154296875, 6062.55078125)
        while task.wait(1) do
            if _G.BossSummonSoul then
                pcall(function()
                    if findBoss("Soul Reaper") then return end
                    local ch = __LP.Character
                    if not ch or not ch:FindFirstChild("HumanoidRootPart") then return end
                    if __LP.Backpack:FindFirstChild("Hallow Essence") or ch:FindFirstChild("Hallow Essence") then
                        repeat
                            Tween2(spot)
                            task.wait()
                        until not _G.BossSummonSoul or (spot.Position - ch.HumanoidRootPart.Position).Magnitude <= 8
                        if _G.BossSummonSoul then
                            task.wait()
                            EquipTool("Hallow Essence")
                        end
                    end
                end)
            end
        end
    end)

    -- Công tắc tổng: bật / tắt cùng lúc các tự kích hoạt (Rip Indra, Cake Prince, Elite, Soul Reaper)
    local function setT(id, on)
        for _, e in ipairs(_G.AbyToggles or {}) do
            if e.id == id and e.holder.value ~= on then pcall(function() e.proxy:SetValue(on) end) end
        end
    end
    local MASTER_IDS = { "ToggleAutoSummonIndra", "ToggleSpawnCake", "BossSummonEliteToggle", "BossSummonSoulToggle" }
    Tabs.Boss:AddToggle("BossSummonAllToggle", {
        ["Title"] = "Bật Tất Cả Tự Kích Hoạt Boss",
        ["Description"] = "Bật / tắt cùng lúc: Rip Indra, Cake Prince, Elite, Soul Reaper",
        ["Default"] = false
    }):OnChanged(function(v)
        for _, id in ipairs(MASTER_IDS) do setT(id, v) end
    end)
end

