        ["Values"] = raceLabels,
        ["Multi"] = false,
        ["Default"] = 1
    }):OnChanged(function(v) raceSel = v end)
    Tabs.Shop:AddButton({["Title"] = "Đổi Tộc Theo Cách Đã Chọn", ["Callback"] = function()
