-- ============================================================
-- [NEW] PVP: Danh sách người chơi / Auto Aim / Chạy nhanh / Nhảy cao
-- (bọc trong do...end để không tốn thêm biến local của file chính)
-- ============================================================
do
    -- ---------- DANH SÁCH NGƯỜI CHƠI ----------
    local function BuildPlayerList()
        local list = {}
        for _, pl in ipairs(__PL:GetPlayers()) do
            if pl ~= __LP then table.insert(list, pl.Name) end
        end
        table.sort(list)
        return list
    end

    _G.__RefreshPlyList = function()
        local list = BuildPlayerList()
        pcall(function() v899:Refresh(list) end)
        if _G.SelectPly and not __PL:FindFirstChild(_G.SelectPly) then
            _G.SelectPly = nil
        end
        if not _G.SelectPly and list[1] then
            _G.SelectPly = list[1]
            pcall(function() v899:SetValue(list[1]) end)
        end
        return list
    end

    -- tự cập nhật khi có người vào / ra server
    local _refreshPending = false
    local function QueueRefresh()
        if _refreshPending then return end
        _refreshPending = true
        task.delay(0.5, function()
            _refreshPending = false
            pcall(_G.__RefreshPlyList)
        end)
    end
    __PL.PlayerAdded:Connect(QueueRefresh)
    __PL.PlayerRemoving:Connect(QueueRefresh)
    task.defer(function() pcall(_G.__RefreshPlyList) end)

    -- ---------- AUTO AIM ----------
    Tabs.Player:AddSection("Tự Động Ngắm (Auto Aim)")
    _G.AimMode = "Người Đã Chọn"
    _G.AimRange = 1000
    _G.AimPredict = 0.08

    local vAimMode = Tabs.Player:AddDropdown("DropdownAimMode", {
        ["Title"] = "Chế Độ Ngắm",
        ["Values"] = { "Người Đã Chọn", "Gần Nhất" },
        ["Multi"] = false,
        ["Default"] = 1
    })
    vAimMode:OnChanged(function(m) _G.AimMode = tostring(m) end)

    Tabs.Player:AddToggle("ToggleAutoAim", {
        ["Title"] = "Tự Động Ngắm (Không Xoay Màn Hình)",
        ["Description"] = "Ngắm ngầm: skill và súng bay thẳng vào mục tiêu, camera đứng yên",
        ["Default"] = false
    }):OnChanged(function(v) _G.AutoAim = v end)
    _G.AimMoveCamera = false
    Tabs.Player:AddToggle("ToggleAimMoveCamera", {
        ["Title"] = "Xoay Màn Hình Theo Mục Tiêu",
        ["Description"] = "Tùy chọn: bật nếu muốn camera cũng xoay theo như bản cũ",
        ["Default"] = false
    }):OnChanged(function(v) _G.AimMoveCamera = v end)

    local function GetAimTarget()
        local myChar = __LP.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return nil end
        if string.find(_G.AimMode or "", "Gần", 1, true) then
            local best, bestDist = nil, math.huge
            for _, pl in ipairs(__PL:GetPlayers()) do
                if pl ~= __LP and pl.Character then
                    local hrp = pl.Character:FindFirstChild("HumanoidRootPart")
                    local hum = pl.Character:FindFirstChild("Humanoid")
                    if hrp and hum and hum.Health > 0 then
                        local d = (hrp.Position - myHRP.Position).Magnitude
                        if d < bestDist and d <= _G.AimRange then
                            best, bestDist = hrp, d
                        end
                    end
                end
            end
            return best
        else
            local pl = _G.SelectPly and __PL:FindFirstChild(_G.SelectPly)
            local ch = pl and pl.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChild("Humanoid")
            if hrp and hum and hum.Health > 0 then return hrp end
        end
        return nil
    end

    local function GetAimPos()
        local t = GetAimTarget()
        return t and (t.Position + t.AssemblyLinearVelocity * _G.AimPredict) or nil
    end

    -- Xoay camera: chỉ chạy khi bạn bật thêm nút "Xoay Màn Hình Theo Mục Tiêu"
    RunService.RenderStepped:Connect(function()
        if not (_G.AutoAim and _G.AimMoveCamera) then return end
        local cam = __WS.CurrentCamera
        local aimPos = cam and GetAimPos()
        if aimPos then cam.CFrame = CFrame.new(cam.CFrame.Position, aimPos) end
    end)

    -- Ngắm ngầm: khi GAME gửi vị trí chuột lên server cho skill / súng, đổi vị trí đó thành vị trí mục tiêu.
    -- Chỉ đụng tới remote "RemoteEvent" nằm trong vũ khí đang cầm và "RemoteFunctionShoot" (súng),
    -- và chỉ đổi các giá trị Vector3 là toạ độ xa (bỏ qua vector hướng của đòn đánh thường).
    pcall(function()
        if not (hookmetamethod and getnamecallmethod) then return end
        local old
        local function hook(self, ...)
            if _G.AutoAim and not (checkcaller and checkcaller()) then
                local m = getnamecallmethod()
                if (m == "FireServer" or m == "InvokeServer") and typeof(self) == "Instance" then
                    local name = self.Name
                    if (name == "RemoteEvent" and self.Parent and self.Parent:IsA("Tool")) or name == "RemoteFunctionShoot" then
                        local pos = GetAimPos()
                        if pos then
                            local args = table.pack(...)
                            for i = 1, args.n do
                                local a = args[i]
                                if typeof(a) == "Vector3" and a.Magnitude > 20 then args[i] = pos end
                            end
                            return old(self, table.unpack(args, 1, args.n))
                        end
                    end
                end
            end
            return old(self, ...)
        end
        old = hookmetamethod(game, "__namecall", newcclosure and newcclosure(hook) or hook)
    end)

    -- ---------- CHẠY NHANH / NHẢY CAO (50 - 500) ----------
    Tabs.Player:AddSection("Tốc Độ & Nhảy")
    _G.SpeedValue = 50
    _G.SwimSpeedValue = 50
    _G.JumpValue = 50
    local origWalk, origJump

    Tabs.Player:AddToggle("ToggleCustomSpeed", {
        ["Title"] = "Bật Chạy Nhanh Tùy Chỉnh",
        ["Default"] = false
    }):OnChanged(function(v)
        _G.CustomSpeed = v
        local hum = __LP.Character and __LP.Character:FindFirstChildOfClass("Humanoid")
        if hum then
            if v then
                origWalk = origWalk or hum.WalkSpeed
            elseif origWalk then
                hum.WalkSpeed = origWalk
                origWalk = nil
            end
        end
    end)
    Tabs.Player:AddSlider("SliderCustomSpeed", {
        ["Title"] = "Tốc Độ Chạy",
        ["Description"] = "50 - 500",
        ["Default"] = 50,
        ["Min"] = 50,
        ["Max"] = 500,
        ["Callback"] = function(v)
            _G.SpeedValue = math.clamp(math.floor((tonumber(v) or 50) + 0.5), 50, 500)
        end
    })

    Tabs.Player:AddSlider("SliderSwimSpeed", {
        ["Title"] = "Tốc Độ Bơi",
        ["Description"] = "10 - 500 (chỉnh riêng khi đang ở dưới nước)",
        ["Default"] = 50,
        ["Min"] = 10,
        ["Max"] = 500,
        ["Callback"] = function(v)
            _G.SwimSpeedValue = math.clamp(math.floor((tonumber(v) or 50) + 0.5), 10, 500)
        end
    })

    Tabs.Player:AddToggle("ToggleCustomJump", {
        ["Title"] = "Bật Nhảy Cao Tùy Chỉnh",
        ["Default"] = false
    }):OnChanged(function(v)
        _G.CustomJump = v
        local hum = __LP.Character and __LP.Character:FindFirstChildOfClass("Humanoid")
        if hum then
            if v then
                origJump = origJump or { hum.UseJumpPower, hum.JumpPower, hum.JumpHeight }
            elseif origJump then
                hum.UseJumpPower = origJump[1]
                hum.JumpPower = origJump[2]
                hum.JumpHeight = origJump[3]
                origJump = nil
            end
        end
    end)
    Tabs.Player:AddSlider("SliderCustomJump", {
        ["Title"] = "Độ Cao Nhảy",
        ["Description"] = "50 - 500",
        ["Default"] = 50,
        ["Min"] = 50,
        ["Max"] = 500,
        ["Callback"] = function(v)
            _G.JumpValue = math.clamp(math.floor((tonumber(v) or 50) + 0.5), 50, 500)
        end
    })

    -- Game hay ghi đè WalkSpeed/JumpPower. Trên mặt đất game ghi đè NGAY TRƯỚC bước vật lý nên
    -- chỉ ép ở Heartbeat (sau vật lý) thì tốc độ trên đất bị về bình thường, còn dưới nước game
    -- không ghi đè nên chạy đúng giá trị -> trông như bơi nhanh hơn đi bộ.
    -- Cách sửa: ép ở nhiều thời điểm (RenderStepped cuối cùng, Stepped, Heartbeat, và ngay khi game vừa ghi đè)
    -- và dùng tốc độ riêng cho trạng thái bơi.
    local function _targetWalk(hum)
        if hum:GetState() == Enum.HumanoidStateType.Swimming then
            return _G.SwimSpeedValue
        end
        return _G.SpeedValue
    end

    local function _applyMove()
        if not (_G.CustomSpeed or _G.CustomJump) then return end
        local ch = __LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        if _G.CustomSpeed then
            local want = _targetWalk(hum)
            if hum.WalkSpeed ~= want then hum.WalkSpeed = want end
        end
        if _G.CustomJump then
            if hum.UseJumpPower then
                if hum.JumpPower ~= _G.JumpValue then hum.JumpPower = _G.JumpValue end
            else
                local h = (_G.JumpValue ^ 2) / (2 * __WS.Gravity) -- cùng độ cao với JumpPower tương ứng
                if math.abs(hum.JumpHeight - h) > 0.01 then hum.JumpHeight = h end
            end
        end
    end

    pcall(function() RunService:UnbindFromRenderStep("AbyCustomMove") end)
    RunService:BindToRenderStep("AbyCustomMove", Enum.RenderPriority.Last.Value + 1, _applyMove)
    RunService.Stepped:Connect(_applyMove)
    RunService.Heartbeat:Connect(_applyMove)

    -- Ép lại ngay khi game vừa ghi đè WalkSpeed (kể cả khi nhân vật hồi sinh)
    local function _watchHumanoid(char)
        local hum = char:WaitForChild("Humanoid", 10)
        if not hum then return end
        hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if _G.CustomSpeed then
                local want = _targetWalk(hum)
                if hum.WalkSpeed ~= want then hum.WalkSpeed = want end
            end
        end)
    end
    if __LP.Character then task.spawn(_watchHumanoid, __LP.Character) end
    __LP.CharacterAdded:Connect(function(c) task.spawn(_watchHumanoid, c) end)
end
