function _G.AbyRaidStage()
    local n = 0
    pcall(function()
        local loc = __WS._WorldOrigin:FindFirstChild("Locations")
        if loc then
            for i = 5, 1, -1 do
                if loc:FindFirstChild("Island " .. i) then n = i break end
            end
        end
    end)
    return n
end
