                raceInfo:SetDesc(string.format("Tộc: %s\nPhiên bản: %s\nNăng lượng tộc: %d%%\nAwakening (V4): %s\nFragments: %s",
                    race, verText, pct,
                    (transformed and transformed.Value) and "Đang bật" or "Đang tắt",
                    tostring(__LP.Data.Fragments.Value)))
            end)
        end
    end)
