		v1134:GetPropertyChangedSignal("JumpPower"):Connect(function()
			if _G.CustomJump then return end -- đang bật nhảy cao tùy chỉnh ở tab PVP thì không ép lại
			v1134.JumpPower = getgenv().JumpValue
		end)
	end
end

